{
  "microservices": [
    {
      "microservice_name": "Shipment Booking Service",
      "responsibility": "Register new shipments with origin, destination, and delivery deadline from controlled location lists, assign unique tracking identifiers, associate selected routes, and support destination change/replanning triggers. Provides the booking web/REST interface and consolidated administrative views grouped by business status (unrouted, in transit, collected).",
      "communicates_with": [
        "Routing Service",
        "Logistics Event Service",
        "Shipment Tracking Service"
      ]
    },
    {
      "microservice_name": "Routing Service",
      "responsibility": "Compute and query candidate routes compatible with a shipment's origin, final destination, and delivery deadline; present route legs (loading/unloading points, trips, planned dates); and reassess routes when destination changes or shipments deviate. Wraps the pathfinder graph-traversal subsystem.",
      "communicates_with": []
    },
    {
      "microservice_name": "Logistics Event Service",
      "responsibility": "Record receipt, loading, unloading, customs, and pickup events tied to an existing shipment, location, and (for loading/unloading) trip; validate and reject invalid events; recalculate transport status, known location, next step, and plan adherence; and mark arrival, completion, and off-route conditions. Accepts events via operational REST, mobile, and periodic file processing channels using a unified event model.",
      "communicates_with": [
        "Shipment Booking Service",
        "Shipment Tracking Service"
      ]
    },
    {
      "microservice_name": "Shipment Tracking Service",
      "responsibility": "Look up a shipment by tracking identifier to present current status, last known location, ETA, event history (distinguishing expected from off-plan events), and geographic support. Maintains traceability sufficient to reconstruct the shipment lifecycle including occurrence/recording times and rejected attempts, keeping a unique tracking model across all channels.",
      "communicates_with": [
        "Logistics Event Service"
      ]
    }
  ]
}

{
  "microservices": [
    {
      "microservice_name": "Shipment Booking Service",
      "responsibility": "Register new shipments with origin, destination, and delivery deadline from controlled location lists, assign unique tracking identifiers, associate selected routes, and handle destination change/replanning triggers by requesting route reassessment. Provides the booking web/REST interface and consolidated administrative views grouped by business status (unrouted, in transit, collected). Consumes recalculated status from the Logistics Event Service rather than recomputing operational status itself.",
      "communicates_with": [
        "Routing Service",
        "Logistics Event Service",
        "Shipment Tracking Service"
      ]
    },
    {
      "microservice_name": "Routing Service",
      "responsibility": "Compute and query candidate routes compatible with a shipment's origin, final destination, and delivery deadline; present route legs (loading/unloading points, trips, planned dates); and reassess/replan routes when destination changes or shipments deviate. Wraps the pathfinder graph-traversal subsystem. Invoked by Booking (initial routing and destination-change replanning) and by the Logistics Event Service when off-route detection requires reassessment.",
      "communicates_with": []
    },
    {
      "microservice_name": "Logistics Event Service",
      "responsibility": "Record receipt, loading, unloading, customs, and pickup events tied to an existing shipment, location, and (for loading/unloading) trip; validate and reject invalid events; and act as the authoritative owner of status recalculation, computing transport status, known location, next step, and plan adherence, and marking arrival, completion, and off-route conditions. On off-route or deviation detection, requests route reassessment from the Routing Service. Accepts events via operational REST, mobile, and periodic file processing channels using a unified event model. Booking and Tracking consume its recalculated status as read-side consumers.",
      "communicates_with": [
        "Shipment Booking Service",
        "Shipment Tracking Service",
        "Routing Service"
      ]
    },
    {
      "microservice_name": "Shipment Tracking Service",
      "responsibility": "Look up a shipment by tracking identifier to present current status, last known location, ETA, event history (distinguishing expected from off-plan events), and geographic support, reading recalculated status from the Logistics Event Service rather than recomputing it. Maintains traceability sufficient to reconstruct the shipment lifecycle including occurrence/recording times and rejected attempts, keeping a unique tracking model across all channels.",
      "communicates_with": [
        "Logistics Event Service"
      ]
    }
  ]
}

{
  "requires_revision": false,
  "summary": "The four-service decomposition aligns well with both the domain capabilities and the structural clusters. Boundaries follow the natural aggregate/interface seams (booking, routing/pathfinder, handling/event, tracking) rather than technical layers. Interaction declarations are consistent, the read-side status ownership is cleanly assigned to the Logistics Event Service, and multi-channel intake plus traceability are correctly folded into their owning services. Minor asymmetry in the communicates_with declarations is worth noting but does not rise to a material, evidence-backed defect requiring redesign.",
  "issues": [
    {
      "category": "unsupported_interaction",
      "severity": "low",
      "description": "The Routing Service declares an empty communicates_with list, yet both its own responsibility text and the Logistics Event Service and Shipment Booking Service describe invoking it (initial routing, destination-change replanning, off-route reassessment). The inbound edges are declared by callers, so the model is functionally consistent, but Routing's own outbound declaration being empty is defensible (it is a pure computation wrapper over pathfinder). The asymmetry is cosmetic rather than a real coupling error. No revision required, but noted for completeness.",
      "evidence": [
        "Routing Service responsibility: 'Invoked by Booking ... and by the Logistics Event Service'",
        "infrastructure.routing -> domain.model.cargo (count=8); net.java.pathfinder.api consumed by infrastructure.routing",
        "Booking and Logistics Event Service both list 'Routing Service' in communicates_with"
      ],
      "recommendation": "Optionally document that Routing is a called-only service; no structural change needed since inbound edges are already declared by callers."
    }
  ],
  "preserved_decisions": [
    "Assigning authoritative status recalculation to the Logistics Event Service with Booking and Tracking as read-side consumers, matching RF-37/38/49 and the handling->cargo bidirectional coupling.",
    "Keeping routing/pathfinder as a distinct service reflecting the separate net.java.pathfinder package root and infrastructure.routing adapter.",
    "Folding multi-channel intake (REST, mobile, file) into the Logistics Event Service consistent with the shared application/handling dependency path and RNF-48/67 unified model.",
    "Separating Shipment Tracking from Booking despite both reading cargo, matching the distinct interfaces.tracking.web cluster and Monitoring/Tracking capability."
  ]
}
